import sys
import math

class SegmentTree:
    def __init__(self, N):
        self.size = N
        self.segTree = [math.inf] * (4 * N)
        self.vals = [math.inf] * N

    def query(self, l, r):
        if r < 0:
            return math.inf
        return self.queryRange(1, 0, self.size - 1, max(0, l), r)

    def queryRange(self, node, start, end, l, r):
        if l > r:
            return math.inf
        if l == start and r == end:
            return self.segTree[node]
        mid = (start + end) // 2
        return min(
            self.queryRange(node * 2, start, mid, l, min(r, mid)),
            self.queryRange(node * 2 + 1, mid + 1, end, max(l, mid + 1), r)
        )

    def assign(self, index, value):
        self.vals[index] = value
        node = 1
        start = 0
        end = self.size - 1
        while start != end:
            mid = (start + end) // 2
            if index <= mid:
                node = node * 2
                end = mid
            else:
                node = node * 2 + 1
                start = mid + 1
        self.segTree[node] = value
        node //= 2
        while node > 0:
            self.segTree[node] = min(self.segTree[node * 2], self.segTree[node * 2 + 1])
            node //= 2

    def getVal(self, i):
        if i < 0 or i >= len(self.vals):
            return math.inf
        return self.vals[i]

def main():
    input = sys.stdin.read().strip().split()
    N, k = int(input[0]), int(input[1])
    intervals = []
    idx = 2
    for _ in range(k):
        start, end = int(input[idx]), int(input[idx + 1])
        intervals.append([start, end])
        idx += 2
    intervals.append([2 * N, 2 * N])
    position = 0
    dp = [SegmentTree(N + 1), SegmentTree(N + 1)]
    dp[0].assign(0, 0)
    for interval in intervals:
        for j in range(N, -1, -1):
            val = dp[0].getVal(j - (interval[0] - position))
            dp[0].assign(j, val)
        position = interval[1]
        length = interval[1] - interval[0]
        for j in range(N, -1, -1):
            costs = [0, 0]
            for z in range(2):
                twoSwaps = dp[z].query(j - length, j)
                oneSwap = dp[(z + 1) % 2].query(j - length, j)
                if z == 1:
                    noSwap = dp[z].getVal(j)
                else:
                    noSwap = dp[z].getVal(j - length)
                costs[z] = min(twoSwaps + 2, oneSwap + 1, noSwap)
            dp[0].assign(j, costs[0])
            dp[1].assign(j, costs[1])
    res = min(dp[0].query(N, N), dp[1].query(N, N))
    if res >= math.inf:
        print("Hungry")
    else:
        print("Full")
        print(res)

if __name__ == "__main__":
    main()

